Lemma xm_eval_spec : forall bc xm b1 k n cb co m, XMOK bc xm ->
  fst (xm_eval bc xm b1 k n cb co m) = xinsideB bc b1 k (ELit n) cb co m /\ XMOK bc (snd (xm_eval bc xm b1 k n cb co m)).
