Fixpoint in_sidesM (bc : bctx) (xm : xmemo) (D : list (saddr * expr)) (b2 : expr) (k2 n2 : Z) : bool * xmemo :=
  match D with
  | [] => (false, xm)
  | (c, m) :: r => let '(v, xm') := sub_itvM bc xm b2 k2 n2 c m in if v then (true, xm') else in_sidesM bc xm' r b2 k2 n2
  end.
