  RAOK br1 rk (Z.of_nat n) ra ->
  gl_others_apart (GLof f log) rb ra = true ->
  le_scan (gl_find (GLof f log) rb) rk (Z.of_nat n) n sx hints = Some r ->
  log_lookupBF2 bc kd (Some br1) log (map f log) rb rk n sx hints [] = r.
